def numTilePossibilities(tiles: str) -> int:
    from collections import Counter

    count = Counter(tiles)

    def backtrack():
        total = 0
        for char in count:
            if count[char] > 0:
                total += 1
                count[char] -= 1
                total += backtrack()
                count[char] += 1
        return total

    return backtrack()
